sys_script_client.script:
/**
 * ESR - Validate subcategory selection
 *
 * Runs when Subcategory changes on the Employee Issue Ticket form.
 *
 * The Subcategory picker is already filtered to the selected Category by the
 * field's reference qualifier, so a mismatch should not normally be reachable.
 * This script closes the remaining gaps: a value arriving from a URL
 * parameter, a form template, a browser back/forward restore, or a stale form
 * left open while the subcategory record was re-categorised.
 *
 * On a mismatch the value is cleared immediately and the reason is shown
 * against the field, so the user cannot carry an invalid pairing to submit.
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return
    }

    g_form.hideFieldMsg('subcategory', true)

    // Clearing the field is always allowed - Subcategory is optional.
    if (!newValue) {
        return
    }

    var category = g_form.getValue('category')

    // Category not chosen yet: a subcategory cannot be validated against it.
    if (!category) {
        g_form.setValue('subcategory', '')
        g_form.showFieldMsg(
            'subcategory',
            'Select a Category first, then choose a Subcategory.',
            'error',
            false
        )
        return
    }

    try {
        var ga = new GlideAjax('x_412993_employe_1.EsrSubcategoryAjax')
        ga.addParam('sysparm_name', 'validatePair')
        ga.addParam('sysparm_category', category)
        ga.addParam('sysparm_subcategory', newValue)
        ga.getXMLAnswer(function (answer) {
            if (!answer) {
                return
            }

            var result
            try {
                result = JSON.parse(answer)
            } catch (e) {
                return
            }

            if (!result || result.valid) {
                return
            }

            // Ignore a stale response: the user may have changed the selection
            // while the request was in flight.
            if (g_form.getValue('subcategory') !== newValue) {
                return
            }

            g_form.setValue('subcategory', '')
            g_form.showFieldMsg('subcategory', result.message, 'error', false)
        })
    } catch (e) {
        // The server-side business rule remains the authoritative guard.
    }
}
